                        class="margin-slider"
                        aria-label={`${label} margin, rem`}
                        min={range.min}
                        max={range.max}
                        step={range.step}
                        value={value}
                        onInput$={(e) =>
                          emitLayout({
                            ...store.layout,
                            [field]: Number(
                              (e.target as HTMLInputElement).value,
                            ),
                          })
                        }
                      />
                    </label>
                  );
