            style={{
              borderRadius: "2px",
              fontFamily: "var(--font-typewriter)",
              maxHeight: `${store.layoutPanelMaxH}px`,
              overscrollBehavior: "contain",
            }}
            role="dialog"
            aria-label="Page layout"
          >
            <header class="layout-panel-header">
              <h2>Page layout</h2>
              <p>Paper, flow, margins, and running heads.</p>
            </header>

            <fieldset class="layout-section">
              <legend>Paper</legend>
              <div class="flex items-center gap-1 mb-2">
                {(
                  [
                    ["letter", "Letter"],
                    ["a4", "A4"],
                    ["legal", "Legal"],
                  ] as const
                ).map(([value, label]) => (
                  <button
                    key={value}
                    type="button"
                    aria-pressed={
                      resolvePageSetup(store.layout).paper === value
                    }
                    onClick$={() =>
                      emitLayout({ ...store.layout, paper: value })
                    }
                    class="layout-choice"
                  >
                    {label}
                  </button>
                ))}
              </div>
              <div class="flex items-center gap-1 mb-3">
                {(
                  [
                    ["portrait", "Portrait"],
                    ["landscape", "Landscape"],
                  ] as const
                ).map(([value, label]) => (
                  <button
                    key={value}
                    type="button"
                    aria-pressed={
                      resolvePageSetup(store.layout).orientation ===
                      value
                    }
                    onClick$={() =>
                      emitLayout({
                        ...store.layout,
                        orientation: value,
                      })
