                      showMarginGuides: (e.target as HTMLInputElement)
                        .checked,
                    })
                  }
                />
              </label>
            </fieldset>

            {/* Header, footer and page numbers are one subject — the
            running heads — and used to be interleaved with the margin
            guides and each other. */}
