        </p>
      )}
      {store.notePopover.thread.length > 0 && (
        <div class="persona-note-thread space-y-2 pt-2">
          {(() => {
            const pop = store.notePopover!;
            return store.notePopover.thread.map((r) =>
              r.authorKind === "user" ? (
                <div
                  key={r.id}
                  class="flex justify-end"
                  data-author-kind="user"
