                  </div>
                </div>
              ) : (
                <div
                  key={r.id}
                  class="flex justify-start"
                  data-author-kind="persona"
                >
                  <div
                    class="max-w-[85%] px-3 py-2 border text-[0.85rem] leading-5 text-[var(--color-ink)]"
