                  {label}
                </button>
              ))}
            </div>
            <div class="flex items-center gap-1 mb-3">
              {(
                [
                  ["portrait", "Portrait"],
                  ["landscape", "Landscape"],
                ] as const
              ).map(([value, label]) => (
                <button
                  key={value}
                  type="button"
                  aria-pressed={
                    resolvePageSetup(store.layout).orientation ===
                    value
                  }
                  onClick$={() =>
                    emitLayout({
                      ...store.layout,
                      orientation: value,
                    })
                  }
                  class="layout-choice"
                >
                  {label}
                </button>
              ))}
            </div>
          </fieldset>

          <fieldset class="layout-section">
            <legend>Flow</legend>
            <div class="flex items-center gap-1 mb-3">
              {(
                [
                  ["paginated", "Pages"],
                  ["continuous", "Scroll"],
                ] as const
              ).map(([value, label]) => (
                <button
                  key={value}
                  type="button"
                  aria-pressed={
                    resolvePageSetup(store.layout).pagination ===
                    value
                  }
                  onClick$={() =>
                    emitLayout({ ...store.layout, pagination: value })
                  }
                  class="layout-choice"
                >
                  {label}
                </button>
              ))}
            </div>

