  label?: string;
  origin: "model" | "writer";
}

export interface CanvasCluster {
  id: string;
  label: string;
  /** 0–360, used for the column tint. Stable across re-maps. */
  hue?: number;
}

export interface SourceCanvas {
  version: 1;
  folioId: string;
  nodes: CanvasNode[];
  edges: CanvasEdge[];
  clusters: CanvasCluster[];
  viewport: { x: number; y: number; zoom: number };
